def map_offset(offset, blk=1024, ptrs_per_block=256):
    """
    混合索引：10 直接 + 1 一级 + 1 二级 + 1 三级（UNIX inode 风格）。
    给定文件内字节偏移 offset，返回 (区域名, 需要读几个索引块, 该区域第几个逻辑块)。

    每块 blk 字节，每索引块 ptrs_per_block 个块号。
      D  = 10 * blk                      -> 直接块
      L1 = ptrs_per_block * blk          -> 一级间接
      L2 = ptrs_per_block**2 * blk       -> 二级间接
      L3 = ptrs_per_block**3 * blk       -> 三级间接（本例不越界检查上界）
    """
    D = 10 * blk
    L1 = ptrs_per_block * blk
    L2 = ptrs_per_block ** 2 * blk
    L3 = ptrs_per_block ** 3 * blk

    if offset < D:
        return ("直接", 0, offset // blk)
    off = offset - D
    if off < L1:
        return ("一级间接", 1, off // blk)
    off -= L1
    if off < L2:
        return ("二级间接", 2, off // blk)
    off -= L2
    if off < L3:
        return ("三级间接", 3, off // blk)
    return ("越界", -1, -1)


if __name__ == "__main__":
    cases = [0, 1023, 1024, 10 * 1024, 10 * 1024 + 256 * 1024]   # 直接 -> 一级 -> 二级 边界
    for off in cases:
        area, extra, blk_no = map_offset(off)
        print("offset=%-10d 区域=%-8s 额外索引块=%d 区域内块号=%d" % (off, area, extra, blk_no))
    # 期望：0/1023 -> 直接；1024 -> 直接块1（仍 < 10*1024）；10*1024 -> 一级间接第0块；
    #       10*1024+256*1024 -> 二级间接第0块
    total = 10 * 1024 + 256 * 1024 + 256 ** 2 * 1024 + 256 ** 3 * 1024
    print("最大文件 =", total, "字节 =", round(total / 1024 ** 3, 2), "GB")
